use std::cmp::{max, min};

fn solve(n: i8, m: i8) -> (i8, i8) {
    // The second component is the smaller of the two inputs.
    let second = min(n, m);
    // The first component is (n + m - 1) - second, which simplifies to the larger input minus 1.
    let first = max(n, m) - 1;
    (first, second)
}

